package hostedquery

import (
	"errors"
	"fmt"
	"strings"
)

const managedMemoryLockNamespace = 1514145800

// managedMemoryBody leaves the function's original work_mem setting in proconfig.
// PostgreSQL's function GUC frame restores the caller setting on return/error.
// The allowance expression is generated by Go, never supplied by a model.
// Slots last to transaction end: idle transactions reduce boost availability,
// but excess calls always execute the original query with its original memory.
func managedMemoryBody(query, allowanceExpression string) (string, error) {
	if strings.TrimSpace(query) == "" || strings.TrimSpace(allowanceExpression) == "" {
		return "", errors.New("memory wrapper requires validated query and allowance")
	}
	return fmt.Sprintf(`DECLARE
 pt_candidate_kb integer := 0;
 pt_slots integer := 0;
 pt_slot integer;
BEGIN
 BEGIN
  SELECT candidate_kb,slots INTO pt_candidate_kb,pt_slots FROM %s;
 EXCEPTION WHEN OTHERS THEN
  pt_candidate_kb := 0; pt_slots := 0;
 END;
 IF pt_candidate_kb > 0 AND pt_candidate_kb <= 32768 AND pt_slots BETWEEN 1 AND 3 THEN
  FOR pt_slot IN 1..pt_slots LOOP
   IF pg_catalog.pg_try_advisory_xact_lock(%d,pt_slot) THEN
    PERFORM pg_catalog.set_config('work_mem',pt_candidate_kb::text || 'kB',true);
    EXIT;
   END IF;
  END LOOP;
 END IF;
 RETURN (%s);
END`, allowanceExpression, managedMemoryLockNamespace, query), nil
}
